"use client";
import { FaqSection } from "@rhs-ui/marketing/faq-section";
export default function Demo(): React.JSX.Element { return <div className="px-6"><FaqSection description="Useful answers, without the fine print." questions={[{id:"source",question:"Can I change the source?",answer:"Yes. These Free blocks are installed into your own project under the MIT licence. Change the layout, content and styling to fit your work."},{id:"framework",question:"Does this work with Next.js?",answer:"Yes. The components support React and Next.js App Router. Interactive pieces declare their own client boundary."},{id:"motion",question:"What happens with reduced motion?",answer:"Animated values settle immediately when reduced motion is enabled. Content and controls remain available."}]} /></div>; }
